function EXTRA(R,ICON){
 /* hook: the antenna a bare 1 kHz tone would need, and the short rod a 100 MHz carrier needs */
 ICON.cmTower=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${CM_box(0,0,380,160,{fill:'#FFFFFF',st:ORG,sw:3,r:18})}${CM_T(20,40,'1 kHz: λ/4 = 75 km',{fs:26,fw:800,fill:ORG})}${CM_T(20,84,'radiated directly',{fs:22,fill:CM_MUT})}${CM_T(20,116,'taller than any tower',{fs:22,fill:CM_MUT})}
  <polyline points="300,152 330,14 360,152" fill="none" stroke="${ORG}" stroke-width="4" stroke-linejoin="round"/>${[40,70,100,130].map(h=>CM_L(330-(h-14)*30/138,h,330+(h-14)*30/138,h,ORG,3)).join('')}${CM_L(330,14,330,2,ORG,3)}</g>`;
 ICON.cmRod=(x,y)=>`<g transform="translate(${x-190} ${y-80})">${CM_box(0,0,380,160,{fill:'#FFFFFF',st:GRN,sw:3,r:18})}${CM_T(20,40,'100 MHz: λ/4 = 0.75 m',{fs:26,fw:800,fill:GRN})}
  <rect x="40" y="76" width="170" height="70" rx="12" fill="#E3FAF1" stroke="${GRN}" stroke-width="3"/><circle cx="85" cy="111" r="22" fill="none" stroke="${GRN}" stroke-width="3"/>${[0,1,2].map(i=>CM_L(130,96+i*15,190,96+i*15,GRN,3)).join('')}${CM_L(196,76,250,54,GRN,4)}${CM_T(266,112,'a short rod',{fs:22,fill:CM_MUT})}</g>`;
 /* recap pictures: each fills most of its card (about 420 × 330) */
 ICON.cmChain=(x,y)=>{const N=['source','Tx','channel','Rx','dest.'];return `<g transform="translate(${x-210} ${y-165})">${N.map((t,i)=>CM_box(i*86,130,72,64,{fill:i===2?'#E3FAF1':'#FFFFFF',st:i===2?GRN:BLU,sw:3,r:10})+CM_T(i*86+36,170,t,{fs:t.length>5?17:22,fw:800,a:'middle',fill:i===2?GRN:BLU})).join('')}${[0,1,2,3].map(i=>CM_arrow(i*86+72,162,i*86+86,162,INK,2)).join('')}
  ${CM_box(122,24,108,48,{fill:'#E3FAF1',st:GRN,sw:3,r:10})}${CM_T(176,56,'n(t)',{fs:24,fw:800,a:'middle',fill:GRN})}${CM_arrow(208,74,208,126,GRN,3)}${CM_T(210,270,'r(t) = s(t) + n(t)',{fs:28,fw:800,a:'middle'})}</g>`};
 ICON.cmAntenna=(x,y)=>`<g transform="translate(${x-210} ${y-165})"><rect x="0" y="20" width="${(CM_xlog(75000,0,420)).toFixed(1)}" height="80" rx="10" fill="${ORG}"/>${CM_T(CM_xlog(75000,0,420)-16,72,'1 kHz: 75 km',{fs:28,fw:800,a:'end',fill:'#FFFFFF'})}<rect x="0" y="130" width="${(CM_xlog(0.75,0,420)).toFixed(1)}" height="80" rx="10" fill="${GRN}"/>${CM_T(CM_xlog(0.75,0,420)+16,182,'100 MHz: 0.75 m',{fs:28,fw:800,fill:GRN})}${CM_T(210,268,'10⁵ times shorter',{fs:30,fw:800,a:'middle'})}${CM_T(210,306,'log scale of length',{fs:22,a:'middle',fill:CM_MUT})}</g>`;
 ICON.cmCopies=(x,y)=>{const xf=f=>210+f*14;return `<g transform="translate(${x-210} ${y-165})">${CM_L(0,240,420,240,CM_GRY,2)}${CM_curve(t=>2*Math.abs(CM_sinc(t)),-3,3,xf(-3),xf(3),240,80,CM_GRY,3,160,'stroke-dasharray="8 7"')}${CM_curve(t=>Math.abs(CM_sinc(t-10)),7,13,xf(7),xf(13),240,80,GRN,5)}${CM_curve(t=>Math.abs(CM_sinc(t+10)),-13,-7,xf(-13),xf(-7),240,80,GRN,5)}${[[-10,'−10'],[0,'0'],[10,'10 kHz']].map(([f,t])=>CM_T(xf(f),276,t,{fs:24,fw:700,a:'middle',fill:CM_MUT})).join('')}${CM_T(xf(10),140,'1 mV/Hz',{fs:24,fw:800,a:'middle',fill:GRN})}${CM_T(xf(-10),140,'1 mV/Hz',{fs:24,fw:800,a:'middle',fill:GRN})}${CM_T(xf(0),62,'2 mV/Hz',{fs:22,a:'middle',fill:CM_MUT})}</g>`};
}
